namespace CSharpPracticum.Tasks.Level2;
internal class MyStack<T>{private T[] a=new T[4];public int Count{get;private set;}public bool IsEmpty=>Count==0;public void Push(T x){if(Count==a.Length)Array.Resize(ref a,a.Length*2);a[Count++]=x;}public T Pop(){if(IsEmpty)throw new InvalidOperationException();T x=a[--Count];a[Count]=default!;return x;}public T Peek()=>IsEmpty?throw new InvalidOperationException():a[Count-1];}
internal class MyQueue<T>{private T[] a=new T[4];private int head;public int Count{get;private set;}public bool IsEmpty=>Count==0;public void Enqueue(T x){if(Count==a.Length){T[] b=new T[a.Length*2];for(int i=0;i<Count;i++)b[i]=a[(head+i)%a.Length];a=b;head=0;}a[(head+Count++)%a.Length]=x;}public T Dequeue(){if(IsEmpty)throw new InvalidOperationException();T x=a[head];a[head]=default!;head=(head+1)%a.Length;Count--;return x;}public T Peek()=>IsEmpty?throw new InvalidOperationException():a[head];}
internal class Task19_Collections:ITask{public string Title=>"Задание 19: Свой стек/очередь на массиве";public string Description=>"Реализовать стек и очередь на расширяемом массиве.";public string[] Requirements=>new[]{"Стек: Push, Pop, Peek, Count, IsEmpty.","Очередь: Enqueue, Dequeue, Peek, Count, IsEmpty.","Удваивать массив при переполнении.","Pop/Dequeue на пустой коллекции бросает InvalidOperationException."};public void Run(){var s=new MyStack<int>();for(int i=1;i<=5;i++)s.Push(i);Console.WriteLine($"Стек: peek={s.Peek()}, pop={s.Pop()}, count={s.Count}");var q=new MyQueue<int>();for(int i=1;i<=5;i++)q.Enqueue(i);Console.WriteLine($"Очередь: peek={q.Peek()}, dequeue={q.Dequeue()}, count={q.Count}");}}
